"use client";
import { ToastContainer, toast } from "react-toastify";
import { useParams, useRouter } from "next/navigation";
import React, { useEffect, useState } from "react";

interface TimeSlot {
  datetime: Date;
  time: string;
}

const Page = () => {
  const { doctorId, patientId } = useParams();
  const router = useRouter();

  const [slotIndex, setSlotIndex] = useState(0);
  const [slotTime, setSlotTime] = useState("");
  const [docInfo, setDocInfo] = useState<any>(null);
  const [docSlots, setDocSlots] = useState<TimeSlot[][]>([]);
  const [appointments, setAppointments] = useState<{ [key: string]: string[] }>(
    {}
  );

  const daysOfWeek = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];

  const fetchDocInfo = async () => {
    try {
      const res = await fetch(
        `http://localhost:3000/api/v1/doctor/getById/${doctorId}`
      );
      if (!res.ok) throw new Error("Failed to fetch doctor info");

      const data = await res.json();
      setDocInfo(data);
    } catch (error) {
      console.error("Error fetching doctor info:", error);
    }
  };

  const fetchAppointments = async () => {
    try {
      const res = await fetch(
        `http://localhost:3000/api/v1/appointment/getByDoctorId/${doctorId}`
      );
      if (!res.ok) throw new Error("Failed to fetch appointments");

      const data = await res.json();
      if (data.success) {
        setAppointments(data.data);
      }
    } catch (error) {
      console.error("Error fetching appointments:", error);
    }
  };

  const generateAvailableSlots = () => {
    const today = new Date();
    const slots: TimeSlot[][] = [];

    for (let i = 0; i < 30; i++) {
      const currentDate = new Date(today);
      currentDate.setDate(today.getDate() + i);

      const endTime = new Date(currentDate);
      endTime.setHours(21, 0, 0, 0);

      if (i === 0) {
        currentDate.setHours(Math.max(currentDate.getHours() + 1, 10));
        currentDate.setMinutes(currentDate.getMinutes() > 30 ? 30 : 0);
      } else {
        currentDate.setHours(10, 0, 0, 0);
      }

      const timeSlots: TimeSlot[] = [];
      while (currentDate < endTime) {
        const formattedTime = currentDate.toLocaleTimeString([], {
          hour: "2-digit",
          minute: "2-digit",
        });

        const slotDate = `${currentDate.getDate()}_${
          currentDate.getMonth() + 1
        }_${currentDate.getFullYear()}`;
        const isSlotAvailable = !(
          appointments[slotDate] &&
          appointments[slotDate].includes(formattedTime)
        );

        if (isSlotAvailable) {
          timeSlots.push({
            datetime: new Date(currentDate),
            time: formattedTime,
          });
        }

        currentDate.setMinutes(currentDate.getMinutes() + 30);
      }

      slots.push(timeSlots);
    }
    setDocSlots(slots);
  };

  const bookAppointment = async () => {
    try {
      if (!docSlots.length || !docSlots[slotIndex]?.length) {
        console.log(slotTime, doctorId, patientId);
        toast.error("Invalid slot selection");
        return;
      }
      const selectedSlot = docSlots[slotIndex][0];
      const date = new Date(selectedSlot.datetime);

      if (isNaN(date.getTime())) {
        toast.error("Invalid date format");
        return;
      }
      const slotDate = `${date.getDate()}_${
        date.getMonth() + 1
      }_${date.getFullYear()}`;
      if (!slotTime || !doctorId || !patientId) {
        toast.error("Missing required fields");
        return;
      }
      const res = await fetch(
        "http://localhost:3000/api/v1/appointment/create",
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ slotDate, slotTime, doctorId, patientId }),
          credentials: "include",
        }
      );

      const data = await res.json();

      if (data.success) {
        toast.success(data.message);
        fetchAppointments();
        router.push("/my-appointment");
      } else {
        toast.error(data.message);
      }
    } catch (error) {
      console.error("Error booking appointment:", error);
      toast.error("An error occurred. Please try again.");
    }
  };

  useEffect(() => {
    const fetchData = async () => {
      await fetchAppointments();
      await fetchDocInfo();
    };
    fetchData();
  }, [doctorId]);

  useEffect(() => {
   
      generateAvailableSlots();
   
  }, [appointments]);

  return (
    docInfo && (
      <div className="text-gray-200 bg-gray-900 min-h-screen p-6">
        <div className="flex flex-col md:flex-row gap-4">
          <div>
            <img
              className="bg-gray-800 w-full sm:max-w-72 rounded-lg"
              src={
                "data:image/png;base64,"
              }
              alt=""
            />
          </div>
          <div className="flex-1 border border-gray-700 rounded-lg p-8 py-7 bg-gray-800 mx-2 sm:mx-0 mt-[-80px] sm:mt-0">
            <div className="p-4  shadow-md rounded-lg flex flex-col gap-2 w-full">
              <h2 className="text-xl font-bold text-white">
                {docInfo.name}
              </h2>
              <p className="text-white">
                Specialist: {docInfo.specialization}
              </p>
              <p className="text-white">
                Experience: {docInfo.yearsOfExperience} years
              </p>
              <p className="text-white">Contact: {docInfo.contactNumber}</p>
              <p className="text-white">
                Medical license No: {docInfo.medicalLicenseNumber}
              </p>
            </div>
          </div>
        </div>

        <p className="text-lg font-semibold text-gray-300 mt-6">
          Booking Slots
        </p>

        {/* Date Selection */}
        <div className="flex gap-3 items-center w-full overflow-x-auto scrollbar-hide mt-4">
          {docSlots.map((slots, index) => (
            <div
              key={index}
              onClick={() => setSlotIndex(index)}
              className={`text-center py-6 min-w-16 rounded-full cursor-pointer ${
                slotIndex === index
                  ? "bg-sky-600 text-white"
                  : "border border-gray-600 text-gray-300"
              }`}
            >
              <p>{slots[0] && daysOfWeek[slots[0].datetime.getDay()]}</p>
              <p>{slots[0] && slots[0].datetime.getDate()}</p>
            </div>
          ))}
        </div>

        {/* Time Selection */}
        <div className="flex gap-3 items-center w-full overflow-x-auto scrollbar-hide mt-4">
          {docSlots[slotIndex]?.map((slot, index) => (
            <p
              key={index}
              onClick={() => setSlotTime(slot.time)}
              className={`text-sm font-light flex-shrink-0 px-5 py-2 rounded-full cursor-pointer ${
                slot.time === slotTime
                  ? "bg-sky-600 text-white"
                  : "border border-gray-600 text-gray-300"
              }`}
            >
              {slot.time.toLowerCase()}
            </p>
          ))}
        </div>

        <button
          onClick={bookAppointment}
          className="bg-sky-600 text-white text-sm font-light px-14 py-3 rounded-full my-6 hover:bg-sky-500"
        >
          Book an Appointment
        </button>
        <ToastContainer />
      </div>
    )
  );
};

export default Page;
